contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner, uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendAmount);
        // record balance of c before the call
        uint256 balBefore = address(c).balance;

        // attempt call and record whether it reverted
        bool reverted;
        bool ret;
        // setOwner is non-payable; do not send value. Ignore sendAmount except for precondition.
        bool success = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            ret = false;
        } else {
            reverted = false;
            ret = success;
        }

        uint256 balAfter = address(c).balance;

        // General rule: setOwner does not change C's ether balance regardless of inputs or revert
        assert(balAfter == balBefore);
    }
    receive() external payable {}
}

